    insert into public.web_testimonios (nombre, ubicacion, rating, comentario, imagen_url, orden) values
    ('María González', 'Bogotá', 5, 'Excelente servicio. Mi viaje a Cartagena fue inolvidable gracias a D''Spacios Travel. Todo perfectamente organizado.', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=200&q=80', 0),
    ('Carlos Ramírez', 'Medellín', 5, 'Los mejores precios del mercado. Reservé un paquete a Cancún y superó todas mis expectativas. Totalmente recomendados.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80', 1),
    ('Ana Martínez', 'Cali', 5, 'Atención personalizada de primer nivel. Me ayudaron a planificar cada detalle de mi luna de miel en Punta Cana.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=200&q=80', 2);
    insert into public.web_blog (titulo, slug, categoria, fecha, resumen, contenido, imagen_url, orden) values
    ('10 Tips para viajar barato a Europa', '10-tips-para-viajar-barato-a-europa', 'Consejos', '15 Oct 2023', 'Descubre cómo ahorrar en vuelos, alojamiento y comida durante tu eurotrip soñado.', 'Viajar a Europa no tiene por qué ser costoso. Planificando con antelación, viajando en temporada baja y utilizando pases de tren, puedes ahorrar significativamente...', 'https://images.unsplash.com/photo-1471623432079-b009d30b6729?auto=format&fit=crop&w=800&q=80', 0),
    ('Mejores playas del Caribe Colombiano', 'mejores-playas-del-caribe-colombiano', 'Destinos', '28 Sep 2023', 'Una guía completa de las joyas ocultas en la costa caribeña de Colombia.', 'Desde el Cabo de la Vela hasta Capurganá, el Caribe colombiano ofrece una diversidad de playas impresionantes...', 'https://images.unsplash.com/photo-1583531352515-8884af319dc1?auto=format&fit=crop&w=800&q=80', 1),
    ('Documentación necesaria para viajar en 2024', 'documentacion-necesaria-para-viajar-en-2024', 'Trámites', '05 Nov 2023', 'Todo lo que necesitas saber sobre pasaportes, visas y requisitos sanitarios actualizados.', 'Antes de empacar tus maletas, asegúrate de tener toda tu documentación en regla. Revisa la vigencia de tu pasaporte...', 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?auto=format&fit=crop&w=800&q=80', 2);
